table inet filter {
	set portal_staff {
		type ipv4_addr
		timeout 8h
	}

	set portal_web {
		type ipv4_addr
		timeout 8h
	}

	chain input {
		type filter hook input priority filter; policy accept;
	}

	chain forward {
		type filter hook forward priority filter; policy drop;
		ct state established,related accept
		iifname "eth1" oifname "eth2" ip saddr @portal_staff accept
		iifname "eth1" oifname "eth2" ip saddr @portal_web tcp dport { 80, 443 } accept
	}

	chain portal_redirect {
		type nat hook prerouting priority dstnat; policy accept;
		iifname "eth1" ip daddr != 192.168.10.1 tcp dport 80 ip saddr != @portal_staff ip saddr != @portal_web dnat ip to 192.168.10.1:8080
	}
}
table ip nat {
	chain postrouting {
		type nat hook postrouting priority srcnat; policy accept;
		oifname "eth2" ip saddr 192.168.10.0/24 snat to 203.0.113.2
	}

	chain prerouting {
		type nat hook prerouting priority dstnat; policy accept;
	}
}
